<?php
require_once __DIR__.'/../includes/functions.php';admin_required();$message='';$keys=['site_name','whatsapp_admin','payment_bank','payment_account','payment_name','payment_instruction','seo_title','seo_description'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo=db();$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($keys as $key)$q->execute([$key,trim((string)($_POST[$key]??''))]);$message='Settings tersimpan.';}catch(Throwable){$message='Settings gagal disimpan. Pastikan database siap.';}}$values=[];try{$rows=db()->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);foreach($keys as $key)$values[$key]=$rows[$key]??'';}catch(Throwable){foreach($keys as $key)$values[$key]=setting($key,'');}$page_title='Settings';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">CONFIGURATION</span><h1>Website settings</h1></header><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif;?><form method="post" class="form-card"><?=csrf_field()?><label>Nama Website<input name="site_name" value="<?=e($values['site_name'])?>"></label><label>WhatsApp Admin<input name="whatsapp_admin" value="<?=e($values['whatsapp_admin'])?>"></label><label>Bank<input name="payment_bank" value="<?=e($values['payment_bank'])?>"></label><label>Nomor Rekening<input name="payment_account" value="<?=e($values['payment_account'])?>"></label><label>Nama Pemilik<input name="payment_name" value="<?=e($values['payment_name'])?>"></label><label>Instruksi Pembayaran<textarea name="payment_instruction" rows="4"><?=e($values['payment_instruction'])?></textarea></label><label>SEO Title<input name="seo_title" value="<?=e($values['seo_title'])?>"></label><label>SEO Description<textarea name="seo_description" rows="3"><?=e($values['seo_description'])?></textarea></label><button class="button">Simpan Settings</button></form><?php require __DIR__.'/includes/footer.php';?>
